// src/get-head-diff-since-review.ts
import { normalize as normalize2 } from "node:path";
var getHeadDiffSinceReview = async ({
  headSha,
  reviewAssociatedSha,
  baseBranch
}) => {
  const git = simpleGit();
  const headAndReviewSummary = await git.diffSummary([
    `${reviewAssociatedSha}..${headSha}`
  ]);
  const headAndReviewDiff = headAndReviewSummary.files.map(({ file }) => file);
  const mainAndSecondCommitSummary = await git.diffSummary([
    `origin/${baseBranch}...${headSha}`
  ]);
  const mainAndSecondCommitDiff = new Set(mainAndSecondCommitSummary.files.map(({ file }) => file));
  const intersectionFiles = headAndReviewDiff.filter((file) => mainAndSecondCommitDiff.has(file));
  const diffFiles = [];
  const fileRenameRegex = /\{(?<from>.*) => (?<to>.*)\}/u;
  await Promise.all(intersectionFiles.map(async (file) => {
    const fileRenameMatch = fileRenameRegex.exec(file);
    if (fileRenameMatch?.groups) {
      const { from, to } = fileRenameMatch.groups;
      const path1 = normalize2(file.replace(fileRenameRegex, from));
      const path2 = normalize2(file.replace(fileRenameRegex, to));
      diffFiles.push(path1, path2);
      console.debug("Filename change:", path1, path2);
      return;
    }
    const firstFileDiff = await git.diff([
      `origin/${baseBranch}...${reviewAssociatedSha}`,
      file
    ]);
    const secondFileDiff = await git.diff([
      `origin/${baseBranch}...${headSha}`,
      file
    ]);
    if (firstFileDiff.split(`
`).filter((line) => line.startsWith("+") || line.startsWith("-")).join(`
`) !== secondFileDiff.split(`
`).filter((line) => line.startsWith("+") || line.startsWith("-")).join(`
`)) {
      diffFiles.push(file);
    }
  }));
  return diffFiles;
};

// src/group-reviews-by-commit.ts
var yellow = (text) => styleText("yellow", text, { validateStream: false });
var groupReviewsByCommit = async ({
  latestReviews,
  headCommit,
  baseBranch,
  ignoreFiles = []
}) => {
  const codeowners = new import_codeowners.default;
  const git = simpleGit();
  const reviewsWithoutHistory = [];
  const groupedReviewsByCommit = {};
  for (const review of latestReviews) {
    const reviewCommit = review.commit?.oid;
    if (reviewCommit === undefined) {
      reviewsWithoutHistory.push(review);
      continue;
    }
    const basehead = `${reviewCommit}..${headCommit}`;
    if (basehead in groupedReviewsByCommit) {
      groupedReviewsByCommit[basehead].reviews.push(review);
      continue;
    }
    try {
      await git.catFile(["commit", reviewCommit]);
    } catch {
      console.log(`
`, yellow(`Commit '${reviewCommit}' doesn't exist in the history. It may be because it was overwritten by force push or because it's outside of checkout depth.`), `
`, yellow(`Approval by ${review.author?.login} will be removed.`), `
`);
      reviewsWithoutHistory.push(review);
      continue;
    }
    const filesChangedByHeadCommit = await getHeadDiffSinceReview({
      reviewAssociatedSha: reviewCommit,
      headSha: headCommit,
      baseBranch
    });
    debug(`Changes in ${basehead}:
${filesChangedByHeadCommit.join(`
`)}`);
    groupedReviewsByCommit[basehead] = {
      reviews: [review],
      filesChangedByHeadCommit: filesChangedByHeadCommit.filter((filename) => !ignoreFiles.some((pattern) => minimatch(filename, pattern, { dot: true }))).map((filename) => ({
        owners: codeowners.getOwner(filename),
        filename
      }))
    };
  }
  return { reviewsWithoutHistory, groupedReviewsByCommit };
};

// src/calculate-reviews-to-dismiss.ts
var findAuthorsOwningTeam = (teams, teamMembers, authorLogin) => teams.find((team) => {
  if (teamMembers[team]?.includes(authorLogin)) {
    return true;
  }
  debug(`User ${authorLogin} is not member of ${team} team`);
  return false;
});
var calculateReviewToDismiss = async ({
  latestReviews,
  headCommit,
  baseBranch,
  ignoreFiles,
  octokit
}) => {
  const { groupedReviewsByCommit, reviewsWithoutHistory } = await groupReviewsByCommit({
    latestReviews,
    headCommit,
    baseBranch,
    ignoreFiles
  });
  const filesWithoutOwner = [
    ...new Set(Object.values(groupedReviewsByCommit).flatMap(({ filesChangedByHeadCommit }) => filesChangedByHeadCommit.filter(({ owners }) => owners.length === 0).map(({ filename }) => filename)))
  ];
  if (filesWithoutOwner.length > 0) {
    return {
      filesWithoutOwner
    };
  }
  const reviewsToDismiss = [...reviewsWithoutHistory];
  const teamMembers = {};
  for (const { filesChangedByHeadCommit, reviews } of Object.values(groupedReviewsByCommit)) {
    const changedFilesOwners = [
      ...new Set(filesChangedByHeadCommit.flatMap(({ owners }) => owners))
    ];
    const changedFilesTeamOwners = changedFilesOwners.filter((owner) => owner.includes("/")).map((teamOwnership) => teamOwnership.replace("@", ""));
    await Promise.all(changedFilesTeamOwners.filter((team) => !Object.keys(teamMembers).includes(team)).map(async (team) => {
      const teamHandle = team.split("/");
      const teamData = await getTeamData({
        octokit,
        organizationLogin: teamHandle[0],
        teamSlug: teamHandle[1]
      });
      teamMembers[team] = teamData.members;
    }));
    for (const review of reviews) {
      const { author } = review;
      let isDismissed = false;
      console.log(`Considering review from ${author?.login} and file changes between ${review.commit?.oid} (reviewed commit) and ${headCommit} (head commit)`);
      if (review.commit?.oid === headCommit) {
        console.log("The review commit sha is the same as head commit sha. That means that there were no changes since the review, or the base branch was merged/rebased cleanly.");
      } else if (!author || author.login && changedFilesOwners.includes(`@${author.login}`)) {
        const changedFilesOwnedByReviewAuthor = filesChangedByHeadCommit.filter(({ owners }) => owners.includes(`@${author?.login}`)).map(({ filename }) => filename);
        console.log(`Changed files owned by ${author?.login}:
${changedFilesOwnedByReviewAuthor.join(`
`)}`);
        reviewsToDismiss.push(review);
        isDismissed = true;
      } else {
        const owningTeam = findAuthorsOwningTeam(changedFilesTeamOwners, teamMembers, author.login);
        if (owningTeam !== undefined) {
          const changedFilesOwnedByAuthorsTeam = filesChangedByHeadCommit.filter(({ owners }) => owners.includes(`@${owningTeam}`)).map(({ filename }) => filename);
          console.log(`Review author ${author.login} is member of ${owningTeam} team, which owns following changed files:
${changedFilesOwnedByAuthorsTeam.join(`
`)}`);
          reviewsToDismiss.push(review);
          isDismissed = true;
        }
      }
      if (isDismissed) {
        console.log(`The review from ${author?.login} will be dismissed.
`);
      } else {
        console.log(`Review author ${author?.login} doesn't own any of changed files, nor is member of any team owning changed files.
The review from ${author?.login} won't be dismissed.
`);
      }
    }
  }
  return {
    reviewsToDismiss,
    reviewsWithoutHistory
  };
};

// src/dismiss-reviews.ts
