var get = (object, path2) => {
  return path2.reduce((current, nextProperty) => current[nextProperty], object);
};
var set = (object, path2, mutator) => {
  const lastProperty = path2[path2.length - 1];
  const parentPath = [...path2].slice(0, -1);
  const parent = get(object, parentPath);
  if (typeof mutator === "function") {
    parent[lastProperty] = mutator(parent[lastProperty]);
  } else {
    parent[lastProperty] = mutator;
  }
};
var extractPageInfos = (responseData) => {
  const pageInfoPath = findPaginatedResourcePath(responseData);
  return {
    pathInQuery: pageInfoPath,
    pageInfo: get(responseData, [...pageInfoPath, "pageInfo"])
  };
};
var isForwardSearch = (givenPageInfo) => {
  return givenPageInfo.hasOwnProperty("hasNextPage");
};
var getCursorFrom = (pageInfo) => isForwardSearch(pageInfo) ? pageInfo.endCursor : pageInfo.startCursor;
var hasAnotherPage = (pageInfo) => isForwardSearch(pageInfo) ? pageInfo.hasNextPage : pageInfo.hasPreviousPage;
var createIterator = (octokit) => {
  return (query, initialParameters = {}) => {
    let nextPageExists = true;
    let parameters = { ...initialParameters };
    return {
      [Symbol.asyncIterator]: () => ({
        async next() {
          if (!nextPageExists)
            return { done: true, value: {} };
          const response = await octokit.graphql(query, parameters);
          const pageInfoContext = extractPageInfos(response);
          const nextCursorValue = getCursorFrom(pageInfoContext.pageInfo);
          nextPageExists = hasAnotherPage(pageInfoContext.pageInfo);
          if (nextPageExists && nextCursorValue === parameters.cursor) {
            throw new MissingCursorChange(pageInfoContext, nextCursorValue);
          }
          parameters = {
            ...parameters,
            cursor: nextCursorValue
          };
          return { done: false, value: response };
        }
      })
    };
  };
};
var mergeResponses = (response1, response2) => {
  if (Object.keys(response1).length === 0) {
    return Object.assign(response1, response2);
  }
  const path2 = findPaginatedResourcePath(response1);
  const nodesPath = [...path2, "nodes"];
  const newNodes = get(response2, nodesPath);
  if (newNodes) {
    set(response1, nodesPath, (values) => {
      return [...values, ...newNodes];
    });
  }
  const edgesPath = [...path2, "edges"];
  const newEdges = get(response2, edgesPath);
  if (newEdges) {
    set(response1, edgesPath, (values) => {
      return [...values, ...newEdges];
    });
  }
  const pageInfoPath = [...path2, "pageInfo"];
  set(response1, pageInfoPath, get(response2, pageInfoPath));
  return response1;
};
var createPaginate = (octokit) => {
  const iterator2 = createIterator(octokit);
  return async (query, initialParameters = {}) => {
    let mergedResponse = {};
    for await (const response of iterator2(query, initialParameters)) {
      mergedResponse = mergeResponses(mergedResponse, response);
    }
    return mergedResponse;
  };
};
function paginateGraphQL(octokit) {
  return {
    graphql: Object.assign(octokit.graphql, {
      paginate: Object.assign(createPaginate(octokit), {
        iterator: createIterator(octokit)
      })
    })
  };
}

// src/get-octokit.ts
var getOctokit = ({ ghToken }) => {
  const OctokitWithPlugins = Octokit2.plugin(paginateGraphQL);
  return new OctokitWithPlugins({ auth: ghToken });
};

// src/get-pr-data.ts
var getPullRequestQuery2 = `
  query getPrData($nodeId: ID!, $cursor: String) {
    node(id: $nodeId) {
      __typename
      ... on PullRequest {
        commits(last: 1) {
          nodes {
            commit {
              oid
              committedDate
            }
          }
        }
        latestOpinionatedReviews(first: 100, after: $cursor) {
          nodes {
            id
            state
            commit {
              oid
            }
            author {
              __typename
              login
              ... on User {
                id
              }
            }
          }
          pageInfo {
            hasNextPage
            endCursor
          }
        }
      }
    }
  }
`;
var getPrData = async ({
  octokit,
  pullRequestId
}) => {
  const { node: pullRequest } = await octokit.graphql.paginate(getPullRequestQuery2, {
    nodeId: pullRequestId
  });
  if (pullRequest?.__typename !== "PullRequest") {
    throw new Error("The pull request could not be found!");
  }
  if (!pullRequest.commits.nodes) {
    throw new Error("Pull request commits are missing!");
  }
  return {
    commits: pullRequest.commits.nodes.filter(isPresent),
    latestReviews: pullRequest.latestOpinionatedReviews?.nodes?.filter(isPresent) ?? []
  };
};

// src/main.ts
var green = (text) => styleText2("green", text, { validateStream: false });
var yellow2 = (text) => styleText2("yellow", text, { validateStream: false });
var logReviewsToDismiss = (reviewsToDismiss) => {
  debug(`Reviews to dismiss: ${JSON.stringify(reviewsToDismiss, null, 2)}`);
  console.log(green(`Reviews to dismiss: ${reviewsToDismiss.map(({ author }) => author?.login ?? "unknownLogin").join(",")}`));
};
var run = async () => {
  const { ghToken, ignoreFiles, noOwnerAction, forcePushAction } = getInputs();
  const pullRequestContext = context2.payload.pull_request;
  if (!pullRequestContext) {
    throw new Error("No pull_request context found. The action must be triggered by pull_request event.");
  }
  const pullRequestId = pullRequestContext.node_id;
  const octokit = getOctokit({ ghToken });
  const {
    commits: [{ commit: head }],
    latestReviews
  } = await getPrData({
    octokit,
    pullRequestId
  });
  const latestApprovedReviews = latestReviews.filter(({ state, commit }) => isPresent(commit) && state === "APPROVED");
  debug(`Approving reviews: ${JSON.stringify(latestApprovedReviews, null, 2)}`);
  if (latestApprovedReviews.length === 0) {
    console.log(green("No reviews to dismiss!"));
    return;
  }
  try {
    const reviewsToDismissContext = await calculateReviewToDismiss({
      octokit,
      headCommit: head.oid,
      latestReviews: latestApprovedReviews,
      baseBranch: context2.payload.pull_request?.base.ref,
      ignoreFiles
    });
    if (reviewsToDismissContext.reviewsWithoutHistory !== undefined && reviewsToDismissContext.reviewsWithoutHistory.length > 0) {
      logReviewsToDismiss(reviewsToDismissContext.reviewsToDismiss);
      console.log(yellow2(`Files diff can't be resolved for following reviews due to force push:
${reviewsToDismissContext.reviewsWithoutHistory.map(({ author }) => author?.login).join(`
`)}
`));
      if (forcePushAction === "dismiss-none") {
        console.log(yellow2('"force-push-action" is set to "dismiss-none", so no reviews are dismissed.'));
        return;
      }
      await dismissReviews({
        octokit,
        reviewsToDismiss: reviewsToDismissContext.reviewsToDismiss,
        message: `
        <details>
          <summary>Following reviews were removed because related commit was overwritten by force push.</summary>
          <p>
  
          - \`${reviewsToDismissContext.reviewsWithoutHistory.map(({ author }) => author?.login).join("`\n- `")}\`
  
          </p>
        </details>
      `.replaceAll(/  +/gu, " ")
      });
    } else if (reviewsToDismissContext.filesWithoutOwner) {
      logReviewsToDismiss(latestApprovedReviews);
      console.log(yellow2(`Files without owner:
${reviewsToDismissContext.filesWithoutOwner.join(`
`)}`));
      if (noOwnerAction === "dismiss-none") {
        console.log(yellow2('"no-owner-action" is set to "dismiss-none", so no reviews are dismissed.'));
        return;
      }
      await dismissReviews({
        octokit,
        reviewsToDismiss: latestApprovedReviews,
        message: `
          <details>
            <summary>Because some files don’t have owner, all reviews are dismissed.</summary>
            <p>

            If you know who should own following files, consider adding the owner to \`.github/CODEOWNERS\` file.

            - \`${reviewsToDismissContext.filesWithoutOwner.join("`\n- `").replaceAll("_", "&#95;")}\`

            </p>
          </details>
        `.replaceAll(/  +/gu, " ")
      });
    } else if (reviewsToDismissContext.reviewsToDismiss.length > 0) {
      logReviewsToDismiss(reviewsToDismissContext.reviewsToDismiss);
      await dismissReviews({
        octokit,
        reviewsToDismiss: reviewsToDismissContext.reviewsToDismiss,
        message: "Stale reviews were dismissed based on ownership"
      });
    } else {
      console.log(green("No reviews to dismiss!"));
    }
  } catch (error) {
    console.error(error);
    await dismissReviews({
      octokit,
      message: "Some error occurred in `dismiss-stale-reviews` action, all reviews are dismissed.",
      reviewsToDismiss: latestApprovedReviews
    });
  }
};
run().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
